1940	export function getImplementationPath(
1941	  collection: MigrationsJson,
1942	  collectionPath: string,
1943	  name: string
1944	): { path: string; fnSymbol: string } {
1945	  const g = collection.generators?.[name] || collection.schematics?.[name];
1946	  if (!g) {
1947	    throw new Error(
1948	      `Unable to determine implementation path for "${collectionPath}:${name}"`
1949	    );
1950	  }
1951	  const implRelativePathAndMaybeSymbol = g.implementation || g.factory;
1952	  const [implRelativePath, fnSymbol = 'default'] =
1953	    implRelativePathAndMaybeSymbol.split('#');
1954	
1955	  let implPath: string;
1956	
1957	  try {
1958	    implPath = require.resolve(implRelativePath, {
1959	      paths: [dirname(collectionPath)],
1960	    });
1961	  } catch (e) {
1962	    // workaround for a bug in node 12
1963	    implPath = require.resolve(
1964	      `${dirname(collectionPath)}/${implRelativePath}`
1965	    );
1966	  }
1967	
1968	  return { path: implPath, fnSymbol };
1969	}
